--########################################################################################

----------------------------------------------------------------
--- Validate Parameters                                      ---
----------------------------------------------------------------
PROCEDURE validate_parameters(
            p_user_name                    IN VARCHAR2    DEFAULT NULL
           ,p_resp_id                      IN NUMBER      DEFAULT NULL
           ,p_org_id                       IN VARCHAR2    DEFAULT NULL
           ,p_batch_source_id              IN NUMBER      DEFAULT NULL
           ,p_col_name                     IN VARCHAR2    DEFAULT 'INTERFACE_LINE_ATTRIBUTE1'
           ,p_col_value                    IN VARCHAR2    DEFAULT NULL
           ,p_apps_check                   IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 5000
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

IS

  l_revision                  VARCHAR2(25);
  l_date_char                 VARCHAR2(30);
  l_instance                  VARCHAR2(255);
  l_apps_version              VARCHAR2(255);
  l_host                      VARCHAR2(255);
  l_full_hostname             VARCHAR2(255);
  l_key                       VARCHAR2(255);
  l_system_function_var       VARCHAR2(2000);
  l_exists_val                VARCHAR2(2000);
  l_index                     NUMBER:=1;
  l_dbversion                 VARCHAR2(255);
  l_db_name                   VARCHAR2(255);
  l_step                      VARCHAR2(10);
  invalid_parameters EXCEPTION;
  invalid_escape EXCEPTION;

----------------------------------------------------------------
-- Analyzer-specific code: Validation Declarations            --
----------------------------------------------------------------






BEGIN

  l_step := '1';

  print_log(analyzer_title || ' Log File');
  print_log('***************************************************************');

  -- Create global hash for parameters. Numbers required for the output order
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'User Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_user_name,'DISPLAY_BOTH_25_PCNT_WORD');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Responsibility ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_resp_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Organization ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Batch Source ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_batch_source_id,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Column Name';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_col_name,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Column Value';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_col_value,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Include Apps Check';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_apps_check,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  print_log(chr(10)||'Parameter Values before validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  BEGIN

    SELECT max(release_name) INTO l_apps_version
    FROM fnd_product_groups;

    begin
        -- Try to get version using new 19c method
        execute immediate 'select instance_name, host_name, version_full, sys_context(''USERENV'',''DB_NAME'') FROM v$instance'
            into l_instance, l_host, l_dbversion, l_db_name;
    exception when others then
        -- Get version using old method
        SELECT instance_name, host_name, version, sys_context('USERENV','DB_NAME')
        INTO l_instance, l_host, l_dbversion, l_db_name
        FROM v$instance;
    end;
    l_host := nvl(l_host, sys_context('USERENV','SERVER_HOST'));
    l_instance := nvl(l_instance, sys_context('USERENV','INSTANCE_NAME'));

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters gathering instance information: '
      ||sqlerrm);
    raise;
  END;

  l_step := '2';
  BEGIN
    SELECT distinct domain
    INTO l_full_hostname
    FROM (SELECT db_domain AS domain
            FROM fnd_databases
          UNION ALL
          SELECT domain AS domain
          FROM fnd_nodes) domains WHERE domains.domain IS NOT NULL and rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_full_hostname := NULL;
        WHEN OTHERS    THEN
          print_log('Error in validate_parameters gathering instance information: '
          ||sqlerrm);
    END;

  l_step := '3';
-- Revision and date values can be populated by RCS
  l_revision := rtrim(replace('$Revision: 200.58  $','$',''));
  l_revision := ltrim(replace(l_revision,'Revision:',''));
  l_date_char := rtrim(replace('$Date: 2026/01/29 15:21:42 $','$',''));
  l_date_char := ltrim(replace(l_date_char,'Date:',''));
  l_date_char := to_char(to_date(l_date_char,'YYYY/MM/DD HH24:MI:SS'),'DD-MON-YYYY');

  l_step := '4';
-- Create global hash for mapping internal result codes (E, W, S, I) to user friendly result codes (error, warning, successful, information)
  g_result('E') := 'error';
  g_result('W') := 'warning';
  g_result('S') := 'success';
  g_result('I') := 'info';

  l_step := '5';
-- Create global hash for report information
-- Do not report host details (EBSAF-274); reverted by EBSAF-293
  g_rep_info('Host') := regexp_substr(l_host, '^[^.]+');
  -- the host name might already be fully qualified, need to check if it includes the domain before appending it
  IF (l_host LIKE '%.%') THEN
       g_rep_info('FullHost') := l_host;
  ELSE
       g_rep_info('FullHost') := l_host || '.' || l_full_hostname;
  END IF;
  l_step := '6';
  g_rep_info('Instance') := l_instance;
  g_rep_info('DB Name') := l_db_name;
  g_rep_info('DB Version') := l_dbversion;
  g_rep_info('Apps Version') := l_apps_version;
  g_rep_info('File Name') := 'ar_autoinvoice_analyzer.sql';
  g_rep_info('File Version') := l_revision;
  g_rep_info('Framework Version') := RTRIM(g_framework_version, ' ');
  g_rep_info('Execution Date') := to_char(sysdate,'DD-MON-YYYY HH24:MI:SS');
  g_rep_info('Description') := ('The ' || analyzer_title || ' <a href="' || g_cmos_km_url || g_analyzer_doc_id||'" target="_blank">(Note '||g_analyzer_doc_id||')</a> is a self-service health-check script that reviews the overall footprint, analyzes current configurations and settings for the environment and provides feedback and recommendations on best practices. Your application data is not altered in any way when you run this analyzer.');

  l_step := '7';
  IF (g_is_concurrent) THEN
     populate_user_details();
  END IF;

  ------------------------------------------------------------------------------
  -- NOTE: Add code here for validation to the parameters of your diagnostic
  ------------------------------------------------------------------------------
  l_step := '8';


  g_max_output_rows := nvl(p_max_output_rows,20);
  g_debug_mode := nvl(p_debug_mode, 'Y');

debug('begin parameter validation: p_user_name');
IF p_user_name IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter User Name is required.');
   raise invalid_parameters;
END IF;
IF p_user_name IS NOT NULL THEN
BEGIN
SELECT USER_NAME
INTO l_exists_val
FROM FND_USER
WHERE USER_NAME = p_user_name
 AND user_name = nvl(FND_GLOBAL.user_name, user_name)
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Error: Invalid user name.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_user_name failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_user_name');

debug('begin parameter validation: p_resp_id');
IF p_resp_id IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Responsibility ID is required.');
   raise invalid_parameters;
END IF;
IF p_resp_id IS NOT NULL THEN
BEGIN
SELECT RESP.RESPONSIBILITY_ID
INTO l_exists_val
FROM FND_RESPONSIBILITY_VL RESP, FND_USER_RESP_GROUPS RG
WHERE RESP.RESPONSIBILITY_ID = p_resp_id
 AND rg.user_id = decode(FND_GLOBAL.USER_ID, -1, rg.user_id, FND_GLOBAL.USER_ID)
and resp.responsibility_id = rg.responsibility_id
and nvl(rg.end_date,sysdate) >= sysdate
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Error: Invalid responsibility.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_resp_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_resp_id');

debug('begin parameter validation: p_org_id');
IF p_org_id IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Organization ID is required.');
   raise invalid_parameters;
END IF;
IF p_org_id IS NOT NULL THEN
BEGIN
SELECT O.ORGANIZATION_ID
INTO l_exists_val
FROM HR_OPERATING_UNITS O, AR_SYSTEM_PARAMETERS_ALL AR
WHERE O.ORGANIZATION_ID = p_org_id
 AND ar.org_id = o.organization_id
and (mo_global.is_mo_init_done = 'N' or mo_global.check_access(o.organization_id) = 'Y')

 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: Invalid Organization.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_org_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_org_id');

debug('begin parameter validation: p_batch_source_id');
IF p_batch_source_id IS NOT NULL THEN
BEGIN
SELECT BAT.BATCH_SOURCE_ID
INTO l_exists_val
FROM RA_BATCH_SOURCES_ALL BAT
WHERE BAT.BATCH_SOURCE_ID = p_batch_source_id
 AND bat.org_id = p_org_id
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: The Batch Source does not exist in RA_BATCH_SOURCES_ALL.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_batch_source_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
debug('end parameter validation: p_batch_source_id');

debug('begin parameter validation: p_col_name');
IF p_col_name IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Column Name is required.');
   raise invalid_parameters;
END IF;
IF p_col_name IS NOT NULL AND p_col_name NOT IN ( 'INTERFACE_LINE_ATTRIBUTE1','INTERFACE_LINE_ATTRIBUTE10','INTERFACE_LINE_ATTRIBUTE11','INTERFACE_LINE_ATTRIBUTE12','INTERFACE_LINE_ATTRIBUTE13','INTERFACE_LINE_ATTRIBUTE14','INTERFACE_LINE_ATTRIBUTE15','INTERFACE_LINE_ATTRIBUTE2','INTERFACE_LINE_ATTRIBUTE3','INTERFACE_LINE_ATTRIBUTE4','INTERFACE_LINE_ATTRIBUTE5','INTERFACE_LINE_ATTRIBUTE6','INTERFACE_LINE_ATTRIBUTE7','INTERFACE_LINE_ATTRIBUTE8','INTERFACE_LINE_ATTRIBUTE9') THEN
   print_error('INVALID ARGUMENT: Invalid Column Name, enter value INTERFACE_LINE_ATTRIBUTE1 to 15');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_col_name');

debug('begin parameter validation: p_col_value');
IF p_col_value IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Column Value is required.');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_col_value');

debug('begin parameter validation: p_apps_check');
IF p_apps_check IS NULL THEN
   print_error('INVALID ARGUMENT: Parameter Include Apps Check is required.');
   raise invalid_parameters;
END IF;
IF p_apps_check IS NOT NULL AND p_apps_check NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Incorrect value for Include Apps Check parameter: Please enter Y or N.');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_apps_check');


debug('begin parameter validation: p_debug_mode');
IF p_debug_mode IS NOT NULL AND p_debug_mode NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Debug Mode is invalid.  Valid values are Y or N');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_debug_mode');



-- Validation to verify analyzer is run on proper e-Business application version
-- In case validation at the beginning is updated/removed, adding validation here also so execution fails

  IF substr(l_apps_version,1,4) NOT IN ('12.0','12.1','12.2') THEN
    print_log('eBusiness Suite version = '||l_apps_version);
    print_log('ERROR: This Analyzer script is compatible for following version(s): 12.0,12.1,12.2');
    raise invalid_parameters;
  END IF;

-- .log enhancements (ER # 140)
  print_log(chr(10)||'Instance Information:');
  print_log('---------------------------');
  -- Do not report host details (EBSAF-274); reverted by EBSAF-293
  print_log('Host: '||g_rep_info('Host'));
  print_log('FullHost: '||g_rep_info('FullHost'));
  print_log('Instance: '||g_rep_info('Instance'));
  print_log('Database name: '||g_rep_info('DB Name'));
  print_log('Database version: '||g_rep_info('DB Version'));
  print_log('Applications version: '||g_rep_info('Apps Version'));
  print_log('Analyzer version: '||g_rep_info('File Version'));
  -- Report call details for troubleshooting (EBSAF-265)
  print_log('Calling method: '||g_rep_info('Calling From') );
  print_log('Calling module: '||g_rep_info('Calling Module') );
  print_log('---------------------------');

  -- Log session details (EBSAF-308)
  l_step := '8.5';
  print_log(chr(10)||'Session Information:');
  print_log('---------------------------');
  print_log('Language Code: '||sys_context('USERENV', 'LANG'));
  print_log('Region: '||sys_context('USERENV', 'NLS_TERRITORY'));
  print_log('Locale: '||sys_context('USERENV', 'LANGUAGE'));
  print_log('Date Format: '||sys_context('USERENV', 'NLS_DATE_FORMAT'));
  -- Get number characters
  select max(value) into l_system_function_var from v$parameter where name = 'nls_numeric_characters';
  print_log('Number Characters: '||l_system_function_var);
  -- Check for language installation
  begin
    execute immediate 'select max(installed_flag) from FND_LANGUAGES where language_code = sys_context(''USERENV'', ''LANG'')' into l_system_function_var;
    if (l_system_function_var is null or l_system_function_var not in ('B', 'I')) then
      print_log('WARNING: FND_LANGUAGES shows the session language is not installed.');
      print_log('Signatures relying on translation information may have incorrect results.');
    end if;
  exception when others then
    print_log('WARNING: Failed to check FND_LANGUAGES if session language is installed.');
  end;
  print_log('---------------------------');

  -- Verify escape character is set properly (EBSAF-265)
  l_step := '9';
  IF regexp_replace('Replace Test', '\s', '*') <>
     regexp_replace('Replace Test', chr(92) || 's', '*') THEN
    print_log('Invalid Escape:  Expected "' || chr(92) || 's' ||'" Received "\s"');
    print_log('Backslash character was not escaped properly during installation or execution.');
    raise invalid_escape;
  END IF;

  l_step := '10';
----------------------------------------------------------------
-- Analyzer-specific code: Additional Validation              --
----------------------------------------------------------------
debug('begin Additional Code: Additional Validation');
declare
   TYPE               cursor_type is REF CURSOR;
   c_col              cursor_type;    
   l_sql_stmt         VARCHAR2(4000);
   col_val_ok         NUMBER;

begin

   -- If P_RESP_ID is not null, then analyzer is called from SQL
   -- MU calls analyzer with P_RESP_ID = 0, no need to validate if 0

   IF p_resp_id is not null AND 
      p_resp_id <> 0 THEN
   begin
      SELECT U.RESPONSIBILITY_NAME
      into g_resp_name
      FROM FND_RESPONSIBILITY SP, FND_RESPONSIBILITY_VL U, FND_USER_RESP_GROUPS RG
      WHERE SP.RESPONSIBILITY_ID = p_resp_id
      AND rg.user_id = (select user_id from fnd_user where user_name = p_user_name)
      and u.responsibility_id = sp.responsibility_id
      and u.responsibility_id = rg.responsibility_id 
      and u.application_id = 222
      and nvl(rg.end_date,sysdate) >= sysdate
      and rownum < 2 ;
		
   exception
   when no_data_found then
     print_log('Error: Invalid responsibility ID.');
     raise invalid_parameters;
   end;
   END IF;


   execute immediate 'alter session set NLS_DATE_FORMAT = ''DD-MON-YYYY''';

   -- set global variable with value from either script or concurrent program
   g_user_name := p_user_name;
   g_resp_id := p_resp_id;
   g_org_id := p_org_id;
   g_batch_source_id := p_batch_source_id;

   -- set global variables to hold optional parameters to null
   g_batch_source_name := null;
   g_col_name := p_col_name;
   g_col_value := p_col_value;
   g_derived_batch_id := null;

   -- make the default condition FALSE, so that when col name and col value are not provided
   -- interface table data is not printed
   g_col_condition := ' and 1=2';
   g_col_cond := ' 1 = 2';

   g_sequence_name := null;
   g_auto_trx_numbering_flag := 'N';

   if g_col_name is null and g_col_value is null then
      print_log('Parameters Column Name and Column Value were *not* provided.');

   elsif g_col_name is not null and g_col_value is not null then
      -- validate column value
      l_sql_stmt := 'select count(*) from ra_interface_lines_all ' || ' where ' || g_col_name || 
                    ' = ''' || g_col_value || ''' and org_id = ' || g_org_id;

      print_log('l_sql_stmt = ' || l_sql_stmt);
   
      open c_col for l_sql_stmt;
      fetch c_col into col_val_ok;
      close c_col;

      if col_val_ok = 0 then
         -- if the column name/value condition did not pick up any records, just set them to null
         print_log('Error: Did not find a row wherein ' || g_col_name || ' = ' || g_col_value);
         print_log('Ignoring Column Name and Column Value.');
         g_col_name := null;
         g_col_value := null;
      else
         -- only build condition if *BOTH* Column Name and Column Value are not null, and there are rows for them
         g_col_val_ok := col_val_ok;
         print_log('g_col_val_ok = ' || g_col_val_ok);
         g_cond_title := g_col_name || ' is ' || g_col_value;
         g_col_condition := ' and ' || g_col_name || ' = ' || '''' || g_col_value || '''';
         g_col_cond := g_col_name || ' = ' || '''' || g_col_value || '''';
         g_sql_tokens('##$$COLCONDITION$$##') := g_col_cond; 
      end if;
   else
      print_log('To list interface record details you *MUST PROVIDE BOTH* Column Name and Column Value. ' ||
                'Ignoring Column Name and Column Value.');
      g_col_name := null;
      g_col_value := null;

   end if;

   print_log('g_col_condition = ' || g_col_condition);   
   print_log('g_col_cond = ' || g_col_cond); 


   if g_col_cond <> ' 1 = 2' then
      -- this means that record(s) exist for the provided col_name and col_value, in this case, 
      -- retrieve the batch_source_id from that record

      l_sql_stmt := 'select b.batch_source_id from ra_batch_sources_all b ' ||
                     'where b.name = (select max(int.batch_source_name) from ra_interface_lines_all int where ' ||
                     g_col_cond ||
                     ' and int.org_id = ' || g_org_id || ')' ||
                     ' and b.org_id = ' || g_org_id;

      print_log('l_sql_stmt = ' || l_sql_stmt);
   
      open c_col for l_sql_stmt;
      fetch c_col into g_derived_batch_id;
      close c_col;
      print_log('g_derived_batch_id = ' || g_derived_batch_id);      

      if g_batch_source_id is not null then
      
        if nvl(g_derived_batch_id, g_batch_source_id) <> g_batch_source_id then
               
               -- the batch_source_id parameter does not match the batch_source_id of the interface data, raise a WARNING        
               print_log('*** WARNING WARNING WARNING WARNING WARNING WARNING WARNING ***');
               print_log('The value you entered for parameter Batch Source ID = ' || g_batch_source_id || '.');
               print_log('Whereas, the batch source id for the interface data associated to Col Name/Value = ' || g_derived_batch_id || '.');
               print_log('Please be aware of this inconsistency. The batch info displayed in the analyzer will use the Batch Source ID you provided, which is ' || g_batch_source_id || '.');
        end if;
      else
         -- use derived batch only if no batch was provided
         g_batch_source_id := g_derived_batch_id;  
      end if;
            
   end if;

   -- user provided Batch Source ID, which means analyzer has to pull data like AutoInvoice Setup Diagnostic
   if g_batch_source_id is not null then

      print_log('Parameter = Batch Source Id = ' || g_batch_source_id);
   
      begin
         SELECT decode(batch_source_type,'INV','Manual','FOREIGN','Imported', batch_source_type ), 
                name, 
                to_char(start_date, 'DD-MON-YYYY'), 
                to_char(end_date, 'DD-MON-YYYY'), 
                description,                              
                decode (status,'A','Active','I','Inactive', status ),  
                nvl(auto_batch_numbering_flag,'N'), 
                decode(nvl(auto_batch_numbering_flag,'N'),'N','Not Applicable', to_char(nvl(last_batch_num,-1))), 
                nvl(auto_trx_numbering_flag,'N'),  
                arpt_sql_func_util.get_trx_type_details(default_inv_trx_type, 'NAME') || ' (Id = ' || default_inv_trx_type|| ')',
                (select name 
                 from ra_batch_sources_all a
                 where org_id = g_org_id
                 and a.batch_source_id = b.credit_memo_batch_source_id) || ' (Id = ' || b.credit_memo_batch_source_id || ')', 
                decode(invalid_lines_rule,'Create','Create Invoice','Reject','Reject Invoice', invalid_lines_rule ), 
                gl_date_period_rule, 
                nvl((select name 
                     from ra_grouping_rules a
                     where a.grouping_rule_id = b.grouping_rule_id),'Not Applicable') || ' (Id =  ' || nvl(b.grouping_rule_id,-1) || ')',
                grouping_rule_id,
                nvl(create_clearing_flag, 'N'),
                nvl(allow_sales_credit_flag, 'N'), 
                sold_customer_rule, 
                bill_customer_rule, 
                bill_address_rule, 
                bill_contact_rule, 
                ship_customer_rule, 
                ship_address_rule, 
                ship_contact_rule, 
                receipt_method_rule, 
                customer_bank_account_rule, 
                invoicing_rule_rule, 
                accounting_rule_rule, 
                accounting_flexfield_rule, 
                nvl(derive_date_flag, 'N'),
                term_rule, 
                rev_acc_allocation_rule,  
                cust_trx_type_rule,  
                memo_reason_rule, 
                agreement_rule, 
                memo_line_rule, 
                sales_territory_rule, 
                inventory_item_rule, 
                unit_of_measure_rule, 
                fob_point_rule, 
                ship_via_rule, 
                related_document_rule,  
                salesperson_rule, 
                sales_credit_type_rule, 
                sales_credit_rule, 
                nvl(copy_doc_number_flag, 'N'),
                default_reference, 
                nvl(copy_inv_tidff_to_cm_flag, 'N'),
                receipt_handling_option, 
                nvl(allow_duplicate_trx_num_flag, 'N'),
                'RA_TRX_NUMBER_' || batch_source_id || '_' || org_id || '_S',
                arpt_sql_func_util.get_lookup_meaning('PAYMENT_DET_DEF_HIERARCHY', payment_det_def_hierarchy)
         INTO   g_batch_source_type,
                g_batch_source_name, 
                g_start_date, 
                g_end_date, 
                g_description, 
                g_status,
                g_auto_batch_numbering_flag, 
                g_last_batch_num, 
                g_auto_trx_numbering_flag,  
                g_default_inv_trx_type, 
                g_credit_memo_batch_source_id, 
                g_invalid_lines_rule,
                g_gl_date_period_rule, 
                g_grouping_rule_id, 
                g_grouping_rule_id2, 
                g_create_clearing_flag, 
                g_allow_sales_credit_flag, 
                g_sold_customer_rule, 
                g_bill_customer_rule, 
                g_bill_address_rule, 
                g_bill_contact_rule, 
                g_ship_customer_rule, 
                g_ship_address_rule, 
                g_ship_contact_rule, 
                g_receipt_method_rule, 
                g_customer_bank_account_rule, 
                g_invoicing_rule_rule, 
                g_accounting_rule_rule, 
                g_accounting_flexfield_rule, 
                g_derive_date_flag, 
                g_term_rule, 
                g_rev_acc_allocation_rule,  
                g_cust_trx_type_rule,  
                g_memo_reason_rule, 
                g_agreement_rule, 
                g_memo_line_rule, 
                g_sales_territory_rule, 
                g_inventory_item_rule, 
                g_unit_of_measure_rule, 
                g_fob_point_rule, 
                g_ship_via_rule, 
                g_related_document_rule,  
                g_salesperson_rule, 
                g_sales_credit_type_rule, 
                g_sales_credit_rule, 
                g_copy_doc_number_flag, 
                g_default_reference, 
                g_copy_inv_tidff_to_cm_flag, 
                g_receipt_handling_option, 
                g_allow_duplicate_trx_num_flag,
                g_sequence_name,
                g_pay_hier
          FROM  RA_BATCH_SOURCES_ALL b
          WHERE batch_source_id = g_batch_source_id
          AND   status = 'A' 
          AND   batch_source_type = 'FOREIGN'  
          AND   NVL(start_date, sysdate) <= sysdate  
          AND   NVL(end_date, sysdate)   >= sysdate 
          AND   NVL(org_id, -99) = g_org_id;

          print_log('Getting ALL_SEQUENCES data.');

          begin
             SELECT    to_char(last_number-1),
                       cache_size
             into      g_last_number,
                       g_cache    
             FROM      ALL_SEQUENCES 
             WHERE     sequence_name = g_sequence_name;

         exception
         when no_data_Found then
            print_log('No ALL_SEQUENCES data.');
            g_last_number := 'Not Applicable';
            g_cache := -1;
         end;
     

      exception
      when no_data_found then
         print_log('Error: The batch source id = ' || g_batch_source_id || ' was not found in RA_BATCH_SOURCES_ALL.');
      end;
   else
      print_log('Parameter Batch Source was *not* provided.');      
   end if;


   -- Column Name/Value, Batch Source were *not* provided, which means analyzer will pull all data from RA_INTERFACE_ERRORS_ALL
   if g_col_name is null and g_col_value is null and g_batch_source_id is null then

      print_log('Parameters Column Name, Column Value and Batch Source were *not* provided.');

      begin
      -- check if this org has interface rows to process
      
         select organization_id 
         into   g_org_id
         from   hr_operating_units
         where  g_org_id = organization_id
         and    g_org_id in
           (SELECT DISTINCT il.org_id
            FROM ra_interface_lines_all il
            WHERE il.interface_line_id IS NOT NULL
            UNION
            SELECT DISTINCT il.org_id
            FROM  ra_interface_errors_all il
            UNION
            SELECT DISTINCT il.org_id
            FROM ra_interface_salescredits_all il
            WHERE il.interface_salescredit_id IS NOT NULL
            UNION
            SELECT DISTINCT il.org_id
            FROM ra_interface_distributions_all il
            WHERE il.interface_distribution_id IS NOT NULL);    

          print_log('Found interface rows to process for org_id = ' || g_org_id);                 

     exception
     when no_data_found then

        -- this org has no interface lines to process

        print_log('Org_id = ' || g_org_id || ' does not have interface rows to process.');       

     end;

  end if;

  print_log('Getting AR_SYSTEM_PARAMETERS data.');

   -- pull AR_SYSTEM_PARAMETERS 
   SELECT set_of_books_id,
          change_printed_invoice_flag,
          pay_unrelated_invoices_flag,
          invoice_deletion_flag,
          show_billing_number_flag,
          tax_invoice_print,
          decode(document_seq_gen_level,
                 'WHEN_TRX_COMMITTED','When Saved',
                 'WHEN_TRX_COMPLETED','When Completed','None'),
          --
          allow_late_charges,
          post_billing_item_inclusion,
          late_charge_billing_calc_mode,
          arpt_sql_func_util.get_trx_type_details(late_charge_inv_type_id,'NAME',org_id)
          || ' (Id = ' || late_charge_inv_type_id || ')',
          arpt_sql_func_util.get_trx_type_details(late_charge_dm_type_id,'NAME',org_id)
          || ' (Id = ' || late_charge_dm_type_id || ')',
          arpt_sql_func_util.get_rec_trx_type(finchrg_receivables_trx_id,'NAME')
          || ' (Id = ' || finchrg_receivables_trx_id || ')',
          arpt_sql_func_util.get_rec_trx_type(penalty_rec_trx_id,'NAME')
          || ' (Id = ' || penalty_rec_trx_id || ')',
          (select name from ra_batch_sources_all
           where org_id = g_org_id
           and batch_source_id = late_charge_batch_source_id)
           || ' (Id = ' || late_charge_batch_source_id || ')',
          --
          ai_purge_interface_tables_flag,
          ai_max_memory_in_bytes,
          ai_log_file_message_level,
          ai_acct_flex_key_left_prompt,
          ai_mtl_items_key_left_prompt,
          ai_territory_key_left_prompt,
          (select name from ra_grouping_rules
           where grouping_rule_id = default_grouping_rule_id) || ' (Id = ' || default_grouping_rule_id || ')',
          --
          generate_customer_number,
          auto_site_numbering,
          create_reciprocal_flag,
          l.chart_of_accounts_id
          -- 
          into 
          g_set_of_books_id,
          g_change_printed_invoice_flag,
          g_pay_unrelated_invoices_flag,
          g_invoice_deletion_flag,
