debug('begin add_signature: AR_AI_RA_INTERFACE_ERRORS_ALL');
   l_info('##MASK##INVALID_VALUE'):= 'NO_MASK';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9377',
      p_sig_id                 => 'AR_AI_RA_INTERFACE_ERRORS_ALL',
      p_sig_sql                => 'select INTERFACE_LINE_ID,
INTERFACE_SALESCREDIT_ID,
INTERFACE_DISTRIBUTION_ID,
MESSAGE_TEXT,
INVALID_VALUE,
LINK_TO_LINE_ID,
ORG_ID,
INTERFACE_CONTINGENCY_ID
from RA_INTERFACE_ERRORS_ALL
where interface_line_id in 
(select interface_line_id from RA_INTERFACE_LINES_ALL
 where org_id = ##$$ORGID$$##
 and ##$$COLCONDITION$$##)
and message_text not like (''%ORIG_%_REF%'')
UNION
select INTERFACE_LINE_ID,
INTERFACE_SALESCREDIT_ID,
INTERFACE_DISTRIBUTION_ID,
MESSAGE_TEXT, ##$$A$$##.mask_text(INVALID_VALUE,''##$$M$$##'') INVALID_VALUE,
LINK_TO_LINE_ID,
ORG_ID,
INTERFACE_CONTINGENCY_ID
from RA_INTERFACE_ERRORS_ALL
where interface_line_id in 
(select interface_line_id from RA_INTERFACE_LINES_ALL
 where org_id = ##$$ORGID$$##
 and ##$$COLCONDITION$$##)
and message_text like (''%ORIG_%_REF%'')',
