      p_sig_sql                => 'SELECT  hcsu.*
FROM    hz_cust_site_uses_all hcsu
where   hcsu.CUST_ACCT_SITE_ID in 
(
  select hcas.CUST_ACCT_SITE_ID
  from   HZ_CUST_ACCT_SITES_ALL hcas
  where  hcas.CUST_ACCOUNT_ID in 
  (
    select hca.CUST_ACCOUNT_ID
    from   HZ_CUST_ACCOUNTS hca
    where  hca.CUST_ACCOUNT_ID in 
    (
      select orig_system_bill_customer_id 
      from RA_INTERFACE_LINES_ALL
      where org_id = ##$$ORGID$$##
      and ##$$COLCONDITION$$##
    )
  )
)
ORDER BY    hcsu.last_update_date,    hcsu.org_id,    hcsu.cust_acct_site_id,    hcsu.site_use_code',
