debug('begin add_signature: AR_AI_PROFILE_OPTIONS');
   l_info('##MASK##LEVEL VALUE'):= 'NO_MASK';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7732',
      p_sig_id                 => 'AR_AI_PROFILE_OPTIONS',
      p_sig_sql                => 'SELECT user_profile_option_name "Profile Option",
a.profile_option_value "Profile Value",
DECODE(a.level_id, 10001, ''Site'',
10002, ''Application'',
10003, ''Responsibility'',
10004, ''User'') "Level",
DECODE(a.level_id, 10001, ''Site'',
10002, b.application_short_name,
10003, c.responsibility_name,
10004, ##$$A$$##.mask_text(d.user_name,''##$$M$$##'')) "Level Value",
c.responsibility_id
FROM fnd_profile_option_values a,
fnd_application b,
fnd_responsibility_tl c,
fnd_user d,
fnd_profile_options e,
fnd_profile_options_tl t
WHERE e.profile_option_name in (''AR_ITEM_FLEXFIELD_MODE'', ''AR_DEFAULT_EXCHANGE_RATE_TYPE'', ''AR_MAX_LINES_PER_AI_WORKER'', ''AR_USE_INV_ACCT_FOR_CM_FLAG'',''AR_GATHER_STATS'',''UNIQUE:SEQ_NUMBERS'',
''OE_ID_FLEX_CODE'',''WSH_INVOICE_NUMBERING_METHOD'',''XLA_MO_SECURITY_PROFILE_LEVEL'',''ORG_ID'',''DEFAULT_ORG_ID'')
AND a.profile_option_id = e.profile_option_id
AND a.application_id = e.application_id
AND a.level_value = b.application_id(+)
AND a.level_value = c.responsibility_id(+)
AND a.level_value = d.user_id(+)
AND t.profile_option_name = e.profile_option_name
AND t.LANGUAGE = ''US''
AND nvl(c.LANGUAGE,''US'') = ''US''
AND ((a.level_id = 10003 AND a.level_value = ##$$RESP_ID$$##)
OR (a.level_id = 10004 AND d.user_name = ''##$$USERNAME$$##'')
OR (a.level_id = 10001 )
OR (a.level_id = 10002 ))
ORDER BY e.profile_option_name,
a.level_id DESC',
      p_title                  => 'Profiles impacting AutoInvoice',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This is a data collection of settings for profile options that impact AutoInvoice.
',
      p_solution               => 'Only the system profile options with values defined for the provided responsibility and user are displayed.
',
      p_success_msg            => 'The profile options impacting AutoInvoice do not exist.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: AR_AI_PROFILE_OPTIONS');



debug('begin add_signature: AR_AI_APPLICATION_SETUP');
   l_info('##SHOW_SQL##'):= 'N';
  add_signature(
      p_sig_repo_id            => '7737',
      p_sig_id                 => 'AR_AI_APPLICATION_SETUP',
      p_sig_sql                => 'SELECT 1 "Row", ''Item validation organization is set to '' || b.name  || '' (Id = '' || a.master_organization_id || '').'' Text
FROM OE_SYSTEM_PARAMETERS_ALL a,
HR_ALL_ORGANIZATION_UNITS b
WHERE b.organization_id = a.master_organization_id
AND NVL(a.org_id, -99) = ##$$ORG_ID$$##
union
SELECT 2, count(*) || '' transaction types have class <i>Credit Memo</i>.''
FROM RA_CUST_TRX_TYPES_ALL
WHERE NVL ( start_date, sysdate ) <= sysdate
AND NVL ( end_date, sysdate ) >= sysdate
AND NVL(org_id, -99) = ##$$ORG_ID$$##
and type = ''CM''
union
SELECT 3, count(*) || '' transaction types have class <i>Bills Receivables</i>.''
FROM RA_CUST_TRX_TYPES_ALL
WHERE NVL ( start_date, sysdate ) <= sysdate
AND NVL ( end_date, sysdate ) >= sysdate
AND NVL(org_id, -99) = ##$$ORG_ID$$##
and type = ''BR''
union
SELECT 4, count(*) || '' transaction types have class <i>Chargeback</i>.''
FROM RA_CUST_TRX_TYPES_ALL
WHERE NVL ( start_date, sysdate ) <= sysdate
AND NVL ( end_date, sysdate ) >= sysdate
AND NVL(org_id, -99) = ##$$ORG_ID$$##
and type = ''CB''
union
SELECT 5, count(*) || '' transaction types have class <i>Chargeback</i>.''
FROM RA_CUST_TRX_TYPES_ALL
WHERE NVL ( start_date, sysdate ) <= sysdate
AND NVL ( end_date, sysdate ) >= sysdate
AND NVL(org_id, -99) = ##$$ORG_ID$$##
and type = ''CB''
union
SELECT 6, count(*) || '' transaction types have class <i>Deposit</i>.''
FROM RA_CUST_TRX_TYPES_ALL
WHERE NVL ( start_date, sysdate ) <= sysdate
AND NVL ( end_date, sysdate ) >= sysdate
AND NVL(org_id, -99) = ##$$ORG_ID$$##
and type = ''DEP''
union
SELECT 7, count(*) || '' transaction types have class <i>Debit Memo</i>.''
FROM RA_CUST_TRX_TYPES_ALL
WHERE NVL ( start_date, sysdate ) <= sysdate
AND NVL ( end_date, sysdate ) >= sysdate
AND NVL(org_id, -99) = ##$$ORG_ID$$##
and type = ''DM''
union
SELECT 8, count(*) || '' transaction types have class <i>Guarantee</i>.''
FROM RA_CUST_TRX_TYPES_ALL
WHERE NVL ( start_date, sysdate ) <= sysdate
AND NVL ( end_date, sysdate ) >= sysdate
AND NVL(org_id, -99) = ##$$ORG_ID$$##
and type = ''GUAR''
union
SELECT 9, count(*) || '' transaction types have class <i>Invoice</i>.''
FROM RA_CUST_TRX_TYPES_ALL
WHERE NVL ( start_date, sysdate ) <= sysdate
AND NVL ( end_date, sysdate ) >= sysdate
AND NVL(org_id, -99) = ##$$ORG_ID$$##
and type = ''INV''
union
SELECT   10, count(*) || '' active payment terms are set up.''
FROM     RA_TERMS
WHERE    NVL( start_date_active, sysdate ) <= sysdate 
AND      NVL( end_date_active, sysdate)    >= sysdate
union
SELECT   11, count(*) || '' active salespersons are set up.''
FROM     JTF_RS_SALESREPS   
WHERE    NVL( start_date_active, sysdate ) <= sysdate 
AND      NVL( end_date_active, sysdate )   >= sysdate 
AND      status =''A'' 
union 
SELECT   12, count(*) || '' active units of measures are set up.''
FROM     MTL_UNITS_OF_MEASURE
WHERE    NVL( disable_date, sysdate ) >= sysdate
union
SELECT   13, count(*) || '' active FOB quick codes are set up.''
FROM     FND_LOOKUP_TYPES a,  
         FND_LOOKUP_VALUES b  
WHERE    a.application_id = 222 
AND      a.lookup_type = ''FOB''  
AND      a.lookup_type = b.lookup_type  
AND      b.enabled_flag = ''Y''
union
SELECT   14, count(*) || '' active freight carriers are set up.''  
FROM     ORG_FREIGHT_VL a 
WHERE    NVL( disable_date, sysdate ) >= sysdate 
AND      a.organization_id = ##$$ORG_ID$$##
union
SELECT  15, count(*) || '' active remit-to addresses are set up with countries assigned to it.''
FROM   HZ_CUST_ACCT_SITES_ALL acct_site 
WHERE  NVL(acct_site.org_id, -99) = ##$$ORG_ID$$##
AND    acct_site.cust_acct_site_id IN  
    (  SELECT distinct address_id FROM RA_REMIT_TOS_ALL 
       WHERE  status = ''A'' 
       AND    NVL(org_id, -99) = ##$$ORG_ID$$## ) 
AND    acct_site.status = ''A''
union
SELECT   16, count(*) || '' remit-to addresses are set up with default country and default state assignments.''
FROM     RA_REMIT_TOS_ALL 
WHERE    country = ''DEFAULT''  
and      state   = ''DEFAULT'' 
AND      NVL(org_id, -99)  = ##$$ORG_ID$$##
union
SELECT   17, count(*) || '' active invoicing rules are set up.''
FROM     RA_RULES 
WHERE    type = ''I'' 
AND      status  = ''A''
union
SELECT    18, count(*) || '' active accounting rules are set up.''
FROM      RA_RULES
WHERE     type = ''A'' 
AND       status  = ''A''',
      p_title                  => 'Application Setup',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Displaying application set up information.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('N','Y'),
