debug('begin add_signature: AR_AI_AUTOACCOUNTING_SEG');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7744',
      p_sig_id                 => 'AR_AI_AUTOACCOUNTING_SEG',
      p_sig_sql                => 'SELECT b.segment_name , 
       decode(e.table_name,''RA_CUST_TRX_TYPES'',         ''Transaction Types'', 
                           ''RA_SITE_USES'',              ''Site'', 
                           ''RA_SALESREPS'',              ''Salesreps'', 
                           ''RA_TAXES'',                  ''Taxes'', 
                           ''RA_STD_TRX_LINES'',          ''Standard Lines'', 
                           ''AR_RECEIPT_METHOD_ACCOUNTS'',''Remittance Banks'' , 
                           e.table_name )                "table_name", 
       e.constant 
FROM   FND_ID_FLEX_SEGMENTS_VL b,  
       GL_LEDGERS c, 
       AR_SYSTEM_PARAMETERS_ALL d,  
       RA_ACCOUNT_DEFAULT_SEGMENTS e 
WHERE  b.application_id = 101  
AND    b.id_flex_code = ''GL#''
AND    d.set_of_books_id = c.ledger_id  
AND    b.id_flex_num = c.chart_of_accounts_id 
AND    e.segment = b.application_column_name 
AND    e.gl_default_id = ##$$FK1$$## 
AND    NVL(d.org_id, -99) = ##$$ORG_ID$$##',
      p_title                  => 'AutoAccounting Segments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Displaying AutoAccounting segments.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: AR_AI_AUTOACCOUNTING_SEG');



