debug('begin add_signature: AR_AI_STUCK_INTERFACE_LINES');
   l_info('##MASK##ORIG_SYSTEM_%_REF'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '19552',
      p_sig_id                 => 'AR_AI_STUCK_INTERFACE_LINES',
      p_sig_sql                => 'SELECT ''RA_INTERFACE_LINES_ALL'' TABLE_NAME,
                count(*) COUNT_OF_STUCK_ROWS
FROM  ra_interface_lines_all intfline
WHERE interface_status is null
and   (INTERFACE_LINE_ID is not NULL or
           CUSTOMER_TRX_ID is not null or
           LINK_TO_LINE_ID is not null or
           REQUEST_ID is not null)
and ORG_ID = ##$$ORGID$$##
and ##$$COLCONDITION$$##
group by 1',
      p_title                  => 'Stuck Records in RA_INTERFACE_LINES_ALL',
