debug('begin add_signature: AR_AI_AA_CURRENT_SETUP');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9309',
      p_sig_id                 => 'AR_AI_AA_CURRENT_SETUP',
      p_sig_sql                => 'SELECT decode(a.type,''REV'',''Revenue'',''REC'',''Receivable'',''UNEARN'',''Unearned Revenue'',''UNBILL'',''Unbilled Receivable'',''SUSPENSE'',''AutoInvoice Clearing'') "ACCOUNT TYPE",
e.segment, decode(e.table_name,''RA_SITE_USES'',''Site'',''RA_CUST_TRX_TYPES'',''Transaction Types'',''RA_SALESREPS'',''Salesreps'',''RA_STD_TRX_LINES'',''Standard Lines'') "SOURCED FROM"
FROM FND_ID_FLEX_SEGMENTS_VL b, 
GL_LEDGERS c, 
AR_SYSTEM_PARAMETERS_ALL d, 
RA_ACCOUNT_DEFAULT_SEGMENTS e,
ra_account_defaults_all a
WHERE b.application_id = 101 
AND b.id_flex_code = ''GL#'' 
AND d.set_of_books_id = c.ledger_id 
AND b.id_flex_num = c.chart_of_accounts_id 
AND e.segment = b.application_column_name 
AND a.gl_default_id = e.gl_default_id
and a.type in (''REC'',''REV'',''UNEARN'',''UNBILL'',''SUSPENSE'')
and e.table_name is not null
and d.org_id = a.org_id
and d.org_id = ##$$ORGID$$##
order by 1',
      p_title                  => 'AutoAccounting Setup Sourced from Tables',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Displaying the current AutoAccounting Setup wherein segments are sourced from tables instead of constant values.',
      p_solution               => 'This list is provided as information only, records returned here do not necessarily indicate that there is a problem.
<ul>
<li>This AutoAccounting Setup is defined via <b>Navigation:</b> Setup > Transactions > AutoAccounting</li>
<li>If you encounter errors in AutoAccounting, you are advised to review the records displayed here to see which account types are sourced from tables</li>
<li>The segments sourced from tables are typically the reasons why AutoAccounting cannot successfully build the GL account segments</li>
<li>Please review subsequent signatures for more details on which account types are raising an error, and the recommendation to fix the problem</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: AR_AI_AA_CURRENT_SETUP');



debug('begin add_signature: AR_AI_AG');
   l_info('##MASK##ORIG_SYSTEM_%_REF'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4495',
      p_sig_id                 => 'AR_AI_AG',
