debug('begin add_signature: AR_AI_AA_BATCH_NOT_ALLOW_SALESCRED');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8924',
      p_sig_id                 => 'AR_AI_AA_BATCH_NOT_ALLOW_SALESCRED',
      p_sig_sql                => 'select a.interface_line_id , d.name "BATCH_SOURCE_NAME", a.primary_salesrep_id, a.primary_salesrep_number,  d.allow_sales_credit_flag
