      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: AR_AI_AA_BATCH_NOT_ALLOW_SALESCRED');



debug('begin add_signature: AR_AI_AA_BATCH_NO_ITEM_RULE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8994',
      p_sig_id                 => 'AR_AI_AA_BATCH_NO_ITEM_RULE',
      p_sig_sql                => 'select a.interface_line_id , d.name "BATCH_SOURCE_NAME", d.inventory_item_rule, a.inventory_item_id, a.mtl_system_items_seg1
from ra_interface_lines_all a, ra_batch_sources_all d
where nvl(interface_status,''X'') <> ''P''
and a.batch_source_name = d.name
and d.org_id = ##$$ORGID$$##
and a.org_id = ##$$ORGID$$##
and nvl(d.inventory_item_rule,''X'') = ''X'' 
and ##$$COLCONDITION$$##
and exists 
(SELECT ''Y''
FROM FND_ID_FLEX_SEGMENTS_VL b, 
GL_LEDGERS c, 
AR_SYSTEM_PARAMETERS_ALL d, 
RA_ACCOUNT_DEFAULT_SEGMENTS e,
ra_account_defaults_all a
WHERE b.application_id = 101 
AND b.id_flex_code = ''GL#'' 
AND d.set_of_books_id = c.ledger_id 
AND b.id_flex_num = c.chart_of_accounts_id 
AND e.segment = b.application_column_name 
AND a.gl_default_id = e.gl_default_id
and a.type in (''REV'',''UNEARN'',''UNBILL'',''SUSPENSE'')
and e.table_name = ''RA_STD_TRX_LINES''
and d.org_id = a.org_id
and d.org_id = ##$$ORGID$$##)',
      p_title                  => 'Batch Source is Missing Setup for Inventory Item',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The batch source does not indicate the settings for <em>Inventory Item</em>: Segment or ID.',
      p_solution               => 'Please check the following:<br>
<b>Responsibility:</b> Receivables Manager<br>
<b>Navigation:</b> Setup > Transactions > Sources
<ol><li>Query for Batch Source name shown above</li>
<li>Navigate to the <em>Other Information</em> tab, review the setting for Inventory Item</li>
<li>For <b>Inventory Item</b>, pick either Segment or ID</li>
<li>If the batch shows that Id or Value is picked for Inventory Item and yet you get this error, then please just make a dummy change to reset the values to force the form to save the correct settings to the table</li>
<li>Next, check your interface data to provide the expected value</li>
<li>If you set Inventory Item = ID, then provide a value in RA_INTERFACE_LINES.INVENTORY_ITEM_ID</li>
<li>If you set Inventory Item = Segment, then provide a value in RA_INTERFACE_LINES.MTL_SYSTEM_ITEMS_SEG1 to 20 (to match the segments of your inventory item)</li>
</ol>

For more information on setting up a transaction batch source, please review [1068008/KB626879] Creating Transaction Sources Used For AutoInvoice and the Transactions Workbench.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
