debug('begin add_signature: AR_AI_AA_MULTI_STD_LINES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9007',
      p_sig_id                 => 'AR_AI_AA_MULTI_STD_LINES',
      p_sig_sql                => 'select a.interface_line_id , d.name "BATCH_SOURCE_NAME", d.inventory_item_rule, d.memo_line_rule, a.memo_line_id, a.memo_line_name, a.warehouse_id, a.inventory_item_id,
a.mtl_system_items_seg1, a.mtl_system_items_seg2,  a.mtl_system_items_seg3,  a.mtl_system_items_seg4,  a.mtl_system_items_seg5, a.mtl_system_items_seg6, a.mtl_system_items_seg7,  a.mtl_system_items_seg8,  a.mtl_system_items_seg9,  a.mtl_system_items_seg10, a.mtl_system_items_seg11, a.mtl_system_items_seg12,  a.mtl_system_items_seg13,  a.mtl_system_items_seg14,  a.mtl_system_items_seg15, a.mtl_system_items_seg16, a.mtl_system_items_seg17,  a.mtl_system_items_seg18,  a.mtl_system_items_seg19,  a.mtl_system_items_seg20
from ra_interface_lines_all a, ra_batch_sources_all d
where nvl(interface_status,''X'') <> ''P''
and a.batch_source_name = d.name
and d.org_id = ##$$ORGID$$##
and a.org_id = ##$$ORGID$$##
and (a.memo_line_id is not null or a.memo_line_name is not null)
and (a.inventory_item_id is not null or a.mtl_system_items_seg1 is not null)
and (''##$$AA_OFFSTD$$##'' = ''Y'' or ''##$$AA_REVSTD$$##'' = ''Y'' or ''##$$AA_SUSSTD$$##'' = ''Y'')',
      p_title                  => 'Multiple Standard Lines Data',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'You have incorrectly provided multiple sources for Standard Lines, and AutoAccounting cannot determine which source to use.',
      p_solution               => 'When you define your AutoAccounting to source from Standard Lines, you must provide <b>EITHER</b> Memo Lines or Inventory Items. You should not provide both.<br>
If you provide <b>BOTH</b> Memo Line and Inventory Item information, AutoAccounting cannot determine which you want to use, and will raise an error. <br>

To provide <em>Memo Line</em> as source for AutoAccounting:
<ul>
<li>If your batch source has Memo Line Rule = Value, you should provide RA_INTERFACE_LINES.MEMO_LINE_NAME</li>
<li>If your batch source has Memo Line Rule = ID, you should provide RA_INTERFACE_LINES.MEMO_LINE_ID</li>
</ul>
To provide <em>Inventory Item</em> as source for AutoAccounting:
<ul>
<li>If your batch source has Inventory Item Rule = Segment, you should provide RA_INTERFACE_LINES.MTL_SYSTEM_ITEMS_SEG1 to SEG20 to properly identify the inventory item you want to use</li>
<li>If your batch source has Inventory Item Rule = ID, you should provide RA_INTERFACE_LINES.INVENTORY_ITEM_ID</li>
</ul>
<b>IMPORTANT:</b> Whether you provide Segments or ID, make sure you also provide a valid value in RA_INTERFACE_LINES.WAREHOUSE_ID.
',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: AR_AI_AA_MULTI_STD_LINES');



