debug('begin add_signature: AR_AI_AA_GET_SALES_CCID_REC');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8926',
      p_sig_id                 => 'AR_AI_AA_GET_SALES_CCID_REC',
      p_sig_sql                => 'select a.interface_line_id,   a.primary_salesrep_id, a.primary_salesrep_number, b.name, ''Missing Receivable GL Account'' STATUS
from ra_interface_lines_all a, ra_interface_errors_all c, ra_salesreps_all b, fnd_new_messages d
where nvl(interface_status,''X'') <> ''P''
and a.interface_line_id = c.interface_line_id
and d.message_name = ''1350''
and d.message_text = c.message_text
and a.org_id = ##$$ORGID$$##
and b.org_id = ##$$ORGID$$##
and ((a.primary_salesrep_id is not null
      and a.primary_salesrep_id = b.salesrep_id)
     OR
     (a.primary_salesrep_id is null
      and a.primary_salesrep_number is not null
      and a.primary_salesrep_number = b.salesrep_number ))
and nvl(b.gl_id_rec,-1) = -1
and a.interface_line_id = ##$$FK6$$##
and ''##$$AA_RECSALE$$##'' = ''Y''',
      p_title                  => 'Salesperson is Missing Receivable GL Account',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'You have not setup a GL Account for Receivable for this Salesperson.',
      p_solution               => 'Please define a Receivable Account as follows:<br>
<b>Responsibility:</b> CRM Resource Manager<br>
<b>Navigation:</b> Maintain Resources > Resources
<ol><li>Query for Name shown above </li>
<li>Click on Resource Details button </li>
<li>Navigate to the <em>Receivables</em> tab </li>
<li>Scroll to the right and enter a GL Account in the <b>Receivable Account</b> field </li></ol>',
      p_success_msg            => 'GL Account for Receivable exists for this Salesperson, no action required.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: AR_AI_AA_GET_SALES_CCID_REC');



debug('begin add_signature: AR_AI_AA_GET_SITE_CCID_REC');
   l_info('##MASK##ACCOUNT_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
