   l_info('##MASK##SITE_NUMBER'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9268',
      p_sig_id                 => 'AR_AI_AA_GET_SITE_CCID_REC',
      p_sig_sql                => 'select a.interface_line_id, a.orig_system_bill_address_id, a.orig_system_bill_address_ref, site_use.site_use_id, 
hp.party_name, hca.account_number,  hps.party_site_number "SITE_NUMBER", 
''Missing Receivable GL Account'' STATUS
from ra_interface_lines_all a, ra_interface_errors_all c, fnd_new_messages d,
hz_cust_acct_sites acct_site, hz_cust_site_uses site_use, 
hz_cust_accounts hca, hz_parties hp, hz_party_sites hps
where nvl(interface_status,''X'') <> ''P''
and a.interface_line_id = c.interface_line_id
and d.message_name = ''1350''
and d.message_text = c.message_text
and a.org_id = ##$$ORGID$$##
and nvl(site_use.gl_id_rec,-1) = -1
and a.orig_system_bill_address_ref is not null
and ACCT_SITE.ORIG_SYSTEM_REFERENCE = a.orig_system_bill_address_ref
and ACCT_SITE.CUST_ACCT_SITE_ID = SITE_USE.CUST_ACCT_SITE_ID
and SITE_USE.SITE_USE_CODE = ''BILL_TO''
and hps.party_id = hp.party_id
and hca.party_id = hps.party_id
and ACCT_SITE.cust_account_id = hca.cust_account_id
and ACCT_SITE.party_site_id = hps.party_site_id
and a.interface_line_id = ##$$FK6$$##
and ''##$$AA_RECSITE$$##'' = ''Y''
UNION
select a.interface_line_id, a.orig_system_bill_address_id, a.orig_system_bill_address_ref, site_use.site_use_id, 
hp.party_name, hca.account_number,  hps.party_site_number, 
''Missing Receivable GL Account'' 
from ra_interface_lines_all a, ra_interface_errors_all c, fnd_new_messages d,
hz_cust_acct_sites acct_site, hz_cust_site_uses site_use, 
hz_cust_accounts hca, hz_parties hp, hz_party_sites hps
where nvl(interface_status,''X'') <> ''P''
and a.interface_line_id = c.interface_line_id
and d.message_name = ''1350''
and d.message_text = c.message_text
and a.org_id = ##$$ORGID$$##
and nvl(site_use.gl_id_rec,-1) = -1
and a.orig_system_bill_address_id is not null
and ACCT_SITE.CUST_ACCT_SITE_ID = a.orig_system_bill_address_id
and ACCT_SITE.CUST_ACCT_SITE_ID = SITE_USE.CUST_ACCT_SITE_ID
and SITE_USE.SITE_USE_CODE = ''BILL_TO''
and hps.party_id = hp.party_id
and hca.party_id = hps.party_id
and ACCT_SITE.cust_account_id = hca.cust_account_id
and ACCT_SITE.party_site_id = hps.party_site_id
and a.interface_line_id = ##$$FK6$$##
and ''##$$AA_RECSITE$$##'' = ''Y''',
      p_title                  => 'Site Use is Missing Receivable GL Account',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'You have not setup a GL Account for Receivable for this Site Use.',
      p_solution               => 'Please do the following:<br>
    <b>Responsibility:</b> Receivables Manager<br>
    <b>Navigation:</b> Customers > Customers
    <ol><li>Query for Name = Party Name shown above</li>
        <li>Go to the <em>Account</em> Section and locate Account Number shown above and click on Details icon.</li>
        <li>In the <em>Sites</em> tab, locate Site Number shown above, and click on Details icon.</li>
        <li>Go To <em>Business Purposes</em> tab, and locate the Bill To Record and click on Details Icon.</li>
        <li>Enter a GL account for <b>Receivable</b> </ol>',
      p_success_msg            => 'GL Account for Receivable exists for this Site Use, no action required.',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: AR_AI_AA_GET_SITE_CCID_REC');



