debug('begin add_signature: AR_AI_1350_REC');
   l_info('##MASK##ORIG_SYSTEM_%_REF'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4253',
      p_sig_id                 => 'AR_AI_1350_REC',
      p_sig_sql                => 'SELECT 
intfline.request_id,
intfline.interface_line_id,
intfline.interface_line_id "##$$FK6$$##",
