and nvl(i.segment15,''-X-'') = nvl(a.mtl_system_items_seg15,''-X-'')   and nvl(i.segment16,''-X-'') = nvl(a.mtl_system_items_seg16,''-X-'')  
and nvl(i.segment17,''-X-'') = nvl(a.mtl_system_items_seg17,''-X-'')  and nvl(i.segment18,''-X-'') = nvl(a.mtl_system_items_seg18,''-X-'')    
and nvl(i.segment19,''-X-'') = nvl(a.mtl_system_items_seg19,''-X-'')  and nvl(i.segment20,''-X-'') = nvl(a.mtl_system_items_seg20,''-X-'') ))
