  add_signature(
      p_sig_repo_id            => '4254',
      p_sig_id                 => 'AR_AI_1360_REV',
      p_sig_sql                => 'SELECT 
 intfline.request_id,
 intfline.interface_line_id,
 intfline.interface_line_id "##$$FK7$$##",
