debug('begin add_signature: AR_AI_AA_GET_TRX_CCID_UNBILL');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9246',
      p_sig_id                 => 'AR_AI_AA_GET_TRX_CCID_UNBILL',
      p_sig_sql                => 'select a.interface_line_id , a.cust_trx_type_id, b.name, ''Missing Unbilled Receivable GL Account'' STATUS
from ra_interface_lines_all a, ra_interface_errors_all c, ra_cust_trx_types_all b, fnd_new_messages d
where nvl(interface_status,''X'') <> ''P''
and a.interface_line_id = c.interface_line_id
and d.message_name = ''AR_AUTOACC_COMPLETE_OFFSET''
and d.message_text = c.message_text
and a.org_id = ##$$ORGID$$##
and b.org_id = ##$$ORGID$$##
and (a.invoicing_rule_id = -3 or a.invoicing_rule_name = ''Arrears Invoice'')
and ((a.cust_trx_type_id is not null
and a.cust_trx_type_id = b.cust_trx_type_id)
OR
(a.cust_trx_type_id is null
and a.cust_trx_type_name  is not null
and a.cust_trx_type_name = b.name))
and nvl(b.gl_id_unbilled,-1) = -1
and a.interface_line_id = ##$$FK8$$##
and ''##$$AA_OFFTRX$$##'' = ''Y''',
      p_title                  => 'Transaction Type is Missing Unbilled Receivable GL Account',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'You have not setup a GL Account for Unbilled Receivable for this Transaction Type.',
      p_solution               => 'Please define a GL account as follows:<br>
    <b>Responsibility:</b> Receivables Manager<br>
