debug('begin add_signature: AR_AI_AUTOACC_COMPLETE_OFFSET');
   l_info('##MASK##ORIG_SYSTEM_%_REF'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4203',
      p_sig_id                 => 'AR_AI_AUTOACC_COMPLETE_OFFSET',
      p_sig_sql                => 'SELECT 
intfline.request_id,
intfline.interface_line_id,
intfline.interface_line_id "##$$FK8$$##",
intfline.line_type,
intfline.set_of_books_id,
intfline.batch_source_name,
intfline.gl_date,
intfline.trx_date,
intfline.amount,
intfline.currency_code,
intfline.conversion_type,
intfline.uom_name,
intfline.uom_code,
intfline.description,
intfline.interface_line_context,
intferr.message_text,
intferr.invalid_value,
intfline.sales_order,
intferr.interface_salescredit_id,
intferr.interface_distribution_id,
intfline.primary_salesrep_number,          
intfline.primary_salesrep_id,
intfline.cust_trx_type_name,
intfline.cust_trx_type_id,
intfline.orig_system_bill_customer_ref,
intfline.orig_system_bill_customer_id,
intfline.orig_system_bill_address_ref,
intfline.orig_system_bill_address_id,
intfline.orig_system_bill_contact_ref,
intfline.orig_system_bill_contact_id,
intfline.orig_system_ship_customer_ref,
intfline.orig_system_ship_customer_id,
intfline.orig_system_ship_address_ref,
intfline.orig_system_ship_address_id,
intfline.orig_system_ship_contact_ref,
intfline.orig_system_ship_contact_id,
intfline.fob_point,
intfline.ship_via,
intfline.accounting_rule_name,
intfline.accounting_rule_id,
intfline.agreement_name,
intfline.agreement_id
FROM ra_interface_errors_all intferr,
ra_interface_lines_all intfline,
fnd_new_messages msg
where msg.message_text = intferr.message_text
AND msg.language_code = ''US''
AND intferr.interface_line_id = intfline.interface_line_id
AND intferr.org_id  IN (##$$ORG_ID$$##) 
and msg.message_name = ''AR_AUTOACC_COMPLETE_OFFSET''
and ##$$COLCONDITION$$##',
      p_title                  => 'Complete the offset account assignments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'AutoAccounting was not able to derive the GL Account for Offset: Unearned Revenue or Unbilled Receivable.',
      p_solution               => '<ul>
<li>This typically happens due to incorrect or incomplete setup.</li>
<li>Please expand the error to view which setup you are missing and review the action plans suggested to fix this issue.</li>
<li>If there is no additional error in this section that identifies what setup is missing, it is possible that:<br>
<ul><li>You did not provide the ID or the value needed by AutoAccounting</li>
<li>You provided the value but the ID could not be properly derived from it</li></ul>
Please look for errors prior to this one, that will indicate what is missing or incorrect. <br>
You are advised to fix these errors first, prior to re-running this analyzer.</li> 
<li>For more information, read: [436831/KB755995]  Autoinvoice errors with: Please complete the offset account assignments</li></ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('AR_AI_AA_GET_ITEM_CCID_OFFSET','AR_AI_AA_GET_MEMO_CCID_OFFSET','AR_AI_AA_GET_SALES_CCID_OFFSET','AR_AI_AA_GET_SITE_CCID_UNBILL','AR_AI_AA_GET_SITE_CCID_UNEARN','AR_AI_AA_GET_TRX_CCID_UNBILL','AR_AI_AA_GET_TRX_CCID_UNEARN'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '52'
      );
   l_info.delete;
debug('end add_signature: AR_AI_AUTOACC_COMPLETE_OFFSET');



debug('begin add_signature: AR_AI_AA_GET_ITEM_CCID_CLEARING');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '9004',
      p_sig_id                 => 'AR_AI_AA_GET_ITEM_CCID_CLEARING',
      p_sig_sql                => 'select a.interface_line_id , a.warehouse_id, a.inventory_item_id, i.segment1, ''Missing Revenue GL Account (For Clearing)'' STATUS
from ra_interface_lines_all a, ra_interface_errors_all c,mtl_system_items i, fnd_new_messages d
where nvl(interface_status,''X'') <> ''P''
and a.interface_line_id = c.interface_line_id
and d.message_name in (''AR_RAXTRX-1793'')
and d.message_text = c.message_text
and a.org_id = ##$$ORGID$$##
And a.warehouse_id = i.organization_id
And (
(a.inventory_item_id is not null 
and a.inventory_item_id = i.inventory_item_id)
OR
(a.mtl_system_items_seg1 is not null
and nvl(i.segment1,''-X-'') = nvl(a.mtl_system_items_seg1,''-X-'')  and nvl(i.segment2,''-X-'') = nvl(a.mtl_system_items_seg2,''-X-'')  
and nvl(i.segment3,''-X-'') = nvl(a.mtl_system_items_seg3,''-X-'')  and  nvl(i.segment4,''-X-'') = nvl(a.mtl_system_items_seg4,''-X-'')  
and nvl(i.segment5,''-X-'') = nvl(a.mtl_system_items_seg5,''-X-'')  and nvl(i.segment6,''-X-'') = nvl(a.mtl_system_items_seg6,''-X-'')   
and nvl(i.segment7,''-X-'') = nvl(a.mtl_system_items_seg7,''-X-'')  and nvl(i.segment8,''-X-'') = nvl(a.mtl_system_items_seg8,''-X-'')  
and nvl(i.segment9,''-X-'') = nvl(a.mtl_system_items_seg9,''-X-'')   and nvl(i.segment10,''-X-'') = nvl(a.mtl_system_items_seg10,''-X-'')  
and nvl(i.segment11,''-X-'') = nvl(a.mtl_system_items_seg11,''-X-'')  and nvl(i.segment12,''-X-'') = nvl(a.mtl_system_items_seg12,''-X-'')    
and nvl(i.segment13,''-X-'') = nvl(a.mtl_system_items_seg13,''-X-'')  and nvl(i.segment14,''-X-'') = nvl(a.mtl_system_items_seg14,''-X-'')  
and nvl(i.segment15,''-X-'') = nvl(a.mtl_system_items_seg15,''-X-'')   and nvl(i.segment16,''-X-'') = nvl(a.mtl_system_items_seg16,''-X-'')  
and nvl(i.segment17,''-X-'') = nvl(a.mtl_system_items_seg17,''-X-'')  and nvl(i.segment18,''-X-'') = nvl(a.mtl_system_items_seg18,''-X-'')    
and nvl(i.segment19,''-X-'') = nvl(a.mtl_system_items_seg19,''-X-'')  and nvl(i.segment20,''-X-'') = nvl(a.mtl_system_items_seg20,''-X-'') ))
and nvl(i.sales_account,-1) = -1
and a.interface_line_id = ##$$FK9$$##
and ''##$$AA_SUSSTD$$##'' = ''Y''',
      p_title                  => 'Inventory Item is Missing Revenue GL Account (For Clearing)',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'You have not setup a GL Account for Revenue for this Inventory Item. This missing setup is required for AutoInvoice Clearing.',
      p_solution               => 'Please do the following:<br>
