debug('begin add_signature: AR_AI_RAXTRX-1793_CLEARING');
   l_info('##MASK##ORIG_SYSTEM_%_REF'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4313',
      p_sig_id                 => 'AR_AI_RAXTRX-1793_CLEARING',
      p_sig_sql                => 'SELECT 
       intfline.request_id,
       intfline.interface_line_id,
       intfline.interface_line_id "##$$FK9$$##",
       intfline.line_type,
       intfline.set_of_books_id,
       intfline.batch_source_name,
       intfline.gl_date,
       intfline.trx_date,
       intfline.amount,
       intfline.currency_code,
       intfline.conversion_type,
       intfline.uom_name,
       intfline.uom_code,
       intfline.description,
       intfline.interface_line_context,
       intferr.message_text,
       intferr.invalid_value,
       intfline.sales_order,
       intferr.interface_salescredit_id,
       intferr.interface_distribution_id,
       intfline.primary_salesrep_number,         
       intfline.primary_salesrep_id,
       intfline.cust_trx_type_name,
       intfline.cust_trx_type_id,
       intfline.orig_system_bill_customer_ref,
       intfline.orig_system_bill_customer_id,
       intfline.orig_system_bill_address_ref,
       intfline.orig_system_bill_address_id,
       intfline.orig_system_bill_contact_ref,
       intfline.orig_system_bill_contact_id,
       intfline.orig_system_ship_customer_ref,
       intfline.orig_system_ship_customer_id,
       intfline.orig_system_ship_address_ref,
       intfline.orig_system_ship_address_id,
       intfline.orig_system_ship_contact_ref,
       intfline.orig_system_ship_contact_id,
       intfline.fob_point,
       intfline.ship_via,
       intfline.accounting_rule_name,
       intfline.accounting_rule_id,
       intfline.agreement_name,
       intfline.agreement_id
FROM ra_interface_errors_all intferr,
     ra_interface_lines_all intfline,
     fnd_new_messages msg
WHERE intferr.interface_line_id = intfline.interface_line_id
AND intferr.org_id = ##$$ORGID$$##
AND ##$$COLCONDITION$$##
AND msg.message_text = intferr.message_text
AND msg.language_code = ''US''
AND msg.message_name = ''AR_RAXTRX-1793''',
      p_title                  => 'Missing AutoInvoice Clearing account',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'You must set up AutoAccounting for AutoInvoice Clearing account if your batch source allows AutoInvoice clearing.',
      p_solution               => '<ul>
<li>This typically happens due to incorrect or incomplete setup.</li>
<li>Please expand the error to view which setup you are missing and review the action plans suggested to fix this issue.</li>
<li>If there is no additional error in this section that identifies what setup is missing, it is possible that:<br>
<ul><li>You did not provide the ID or the value needed by AutoAccounting</li>
<li>You provided the value but the ID could not be properly derived from it</li></ul>
Please look for errors prior to this one, that will indicate what is missing or incorrect. <br>
You are advised to fix these errors first, prior to re-running this analyzer.</li> 
<li>Check that you have completed the AutoAccounting setup for AutoInvoice Clearing, please review details in [1069052/KB449160] Setting Up AutoAccounting Rules In Receivables [Video] </li></ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL('AR_AI_AA_GET_ITEM_CCID_CLEARING','AR_AI_AA_GET_MEMO_CCID_CLEARING','AR_AI_AA_GET_SALES_CCID_CLEARING','AR_AI_AA_GET_SITE_CCID_CLEARING','AR_AI_AA_GET_TRX_CCID_CLEARING'),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '39'
      );
   l_info.delete;
debug('end add_signature: AR_AI_RAXTRX-1793_CLEARING');



