      p_sig_repo_id            => '9276',
      p_sig_id                 => 'AR_AI_AA_LISTERR_SITES',
      p_sig_sql                => 'select hp.party_name, hca.account_number, hps.party_site_number,
decode(nvl(gl_id_rec,-1),-1,''Y'',''N'') "Missing Receivable", decode(nvl(gl_id_rev,-1),-1,''Y'',''N'') "Missing Revenue",
decode(nvl(gl_id_unbilled,-1),-1,''Y'',''N'') "Missing Unbilled Receivable", decode(nvl(gl_id_unearned,-1),-1,''Y'',''N'') "Missing Unearned Revenue",
decode(nvl(gl_id_clearing,-1),-1,''Y'',''N'') "Missing Clearing Account"
from hz_cust_accounts hca, hz_parties hp, hz_party_sites hps, hz_cust_site_uses hcsu, hz_cust_acct_sites hcas
where hps.party_id = hp.party_id
and hca.party_id = hps.party_id
and hcas.cust_account_id = hca.cust_account_id
and hcas.cust_acct_site_id = hcsu.cust_acct_site_id
and hcas.party_site_id = hps.party_site_id
and hcsu.site_use_code = ''BILL_TO''
and hcsu.status = ''A''
and (nvl(gl_id_rec,-1) = -1 or
nvl(gl_id_rev,-1) = -1 or
nvl(gl_id_unbilled,-1) = -1 or
nvl(gl_id_unearned,-1) = -1 or
nvl(gl_id_clearing,-1) = -1)
and (''##$$AA_RECSITE$$##'' = ''Y'' or ''##$$AA_OFFSITE$$##'' = ''Y'' or ''##$$AA_REVSITE$$##'' = ''Y'' or ''##$$AA_SUSSITE$$##'' = ''Y'')',
      p_title                  => 'Site Use Records with Incomplete GL Account Setup',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This list shows other Site Use records in your instance that have incomplete GL Account Setup.',
      p_solution               => 'If you use any of these Site Uses in a transaction, and your AutoAccounting is sourced from Site Use, you will encounter errors in AutoAccounting.     
    You are advised to fix these records as follows:<br>
    <b>Responsibility:</b> Receivables Manager<br>
    <b>Navigation:</b> Customers > Customers
    <ol><li>Query for Name = Party Name shown above</li>
        <li>Go to the <em>Account</em> Section and locate Account Number as shown above and click on Details icon.</li>
        <li>In the <em>Sites</em> tab, locate Site Number as shown above, and click on Details icon.</li>
        <li>Go To <em>Business Purposes</em> tab, and locate the Bill To Record and Click on Details Icon.</li>
        <li>Review and Complete the missing GL account</ol>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: AR_AI_AA_LISTERR_SITES');



