debug('begin add_signature: AR_AI_SYS_GATHER_STATS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4471',
      p_sig_id                 => 'AR_AI_SYS_GATHER_STATS',
      p_sig_sql                => 'SELECT OPT.PROFILE_OPTION_ID,
       ''AR: AutoInvoice Gather Statistics'' profile_option_name,
       ''No'' PROFILE_OPTION_VALUE
FROM fnd_profile_options opt,
     FND_PROFILE_OPTION_VALUES val
WHERE OPT.PROFILE_OPTION_ID = VAL.PROFILE_OPTION_ID
AND   opt.profile_option_name = ''AR_GATHER_STATS''
AND   OPT.APPLICATION_ID      = 222
AND   val.level_id            = 10001
AND   PROFILE_OPTION_VALUE    = ''N''',
      p_title                  => 'Profile Options Setup: AR: AutoInvoice Gather Statistics',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This profile option determines if the AutoInvoice Master program analyzes and gathers information about the interface tables each time AutoInvoice is run. Gathering statistics on a table can tie up system resources, however, once statistics are gathered performance of processes using this data improves.<br><br>

<ul>
<li>If the value for this profile option is set to Yes, or is null, AutoInvoice analyzes the interface tables and gathers statistics.</li>
<li>If the value is set to No, AutoInvoice does not analyze the interface tables.</li>
</ul>',
      p_solution               => 'Profile Options should be set correctly to derive the best performance out of AutoInvoice program. <br><br>For more information, read: [1083467/KB785164] How To Setup AutoInvoice For Optimal Performance. In general, the recommended setting is Y (Yes) at the Site level.<br><br>There are some exceptions when this profile option must be set to N (No). For more information, read: [1573162/KB774921] AutoInvoice Performance Issue when Profile Option "AR: AutoInvoice Gather Statistics" is Set to Yes and Autoinvoice is Executed too Often.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: AR_AI_SYS_GATHER_STATS');



debug('begin add_signature: AR_AI_SYS_MAX_LINES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4470',
      p_sig_id                 => 'AR_AI_SYS_MAX_LINES',
      p_sig_sql                => 'SELECT OPT.PROFILE_OPTION_ID,
  ''AR:Maximum lines per AutoInvoice worker'' profile_option_name,
  CASE PROFILE_OPTION_VALUE
    WHEN ''N''
    THEN ''no''
    WHEN ''Y''
    THEN ''Yes''
    ELSE profile_option_value
  END profile_option_value
FROM fnd_profile_options opt,
  FND_PROFILE_OPTION_VALUES val
WHERE OPT.PROFILE_OPTION_ID = VAL.PROFILE_OPTION_ID
AND opt.profile_option_name = ''AR_MAX_LINES_PER_AI_WORKER''
AND OPT.APPLICATION_ID      = 222
AND val.level_id            = 10001',
      p_title                  => 'Profile Options Setup: AR:Maximum lines per AutoInvoice worker',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The lines per worker setting is a guideline and not a hard and fast rule.',
      p_solution               => 'Profile Options should be set correctly for deriving the best performance out of AutoInvoice program. 
<br><br>For more information, read: [1083467/KB785164] How To Setup AutoInvoice For Optimal Performance, This profile option should be set if you are running AutoInvoice Master with multiple workers and your transactions typically have a large number of lines. Setting this profile option will help AutoInvoice determine the maximum number of lines to assign to an AutoInvoice worker. <BR><BR> For example, if you typically process invoices with approximately 10,000 lines per invoice, then set the value = 10,000. If you are unsure, or if the number of lines per transaction are low or varied, you should not enter a value for this profile option.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '2'
      );
   l_info.delete;
debug('end add_signature: AR_AI_SYS_MAX_LINES');



