debug('begin add_signature: AR_AI_INDEXES');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4472',
      p_sig_id                 => 'AR_AI_INDEXES',
      p_sig_sql                => 'SELECT
    table_name,
    interface_line_context,
    sequence_number,
    column_name,
    interface_line_attrib_col,
    nvl(index_exists, ''No'') index_exists
FROM
    (
        SELECT
            ''RA_INTERFACE_LINES_ALL''      table_name,
            descriptive_flex_context_code interface_line_context,
            column_seq_num                sequence_number,
            end_user_column_name          column_name,
            application_column_name       interface_line_attrib_col,
            (
                SELECT
                    nvl(''Yes'', ''No'')
                FROM
                    all_ind_columns
                WHERE
                        table_name = ''RA_INTERFACE_LINES_ALL''
                    AND column_name = application_column_name
                    AND ROWNUM < 2
            )                             index_exists
        FROM
            fnd_descr_flex_col_usage_vl
        WHERE
                application_id = 222
            AND descriptive_flexfield_name = ''RA_INTERFACE_LINES''
            AND descriptive_flex_context_code IN (
                SELECT DISTINCT
                    interface_line_context
                FROM
                    ra_interface_lines_all
            )
        UNION ALL
        SELECT
            ''RA_CUSTOMER_TRX_ALL''                              table_name,
            descriptive_flex_context_code,
            column_seq_num                                     sequence_number,
            end_user_column_name                               column_name,
            replace(application_column_name, ''LINE'', ''HEADER'') interface_line_attrib_col,
            (
                SELECT
                    ''Yes''
                FROM
                    all_ind_columns
                WHERE
                        table_name = ''RA_CUSTOMER_TRX_ALL''
                    AND column_name = replace(application_column_name, ''LINE'', ''HEADER'')
                    AND ROWNUM < 2
            )                                                  index_exists
        FROM
            fnd_descr_flex_col_usage_vl
        WHERE
                application_id = 222
            AND descriptive_flexfield_name = ''RA_INTERFACE_LINES''
            AND descriptive_flex_context_code IN (
                SELECT DISTINCT
                    interface_line_context
                FROM
                    ra_interface_lines_all
            )
        UNION ALL
        SELECT
            ''RA_CUSTOMER_TRX_LINES_ALL'' table_name,
            descriptive_flex_context_code,
            column_seq_num              sequence_number,
            end_user_column_name        column_name,
            application_column_name     interface_line_attrib_col,
            (
                SELECT
                    ''Yes''
                FROM
                    all_ind_columns
                WHERE
                        table_name = ''RA_CUSTOMER_TRX_LINES_ALL''
                    AND column_name = application_column_name
                    AND ROWNUM < 2
            )                           index_exists
        FROM
            fnd_descr_flex_col_usage_vl
        WHERE
                application_id = 222
            AND descriptive_flexfield_name = ''RA_INTERFACE_LINES''
            AND descriptive_flex_context_code IN (
                SELECT DISTINCT
                    interface_line_context
                FROM
                    ra_interface_lines_all
            )
    )
ORDER BY    1,  2,  3',
      p_title                  => 'Index on RA_INTERFACE_LINES Columns',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'There are some ''INTERFACE_LINE_ATTRIBUTE%'' columns that do not have indexes on them in the context they are being used.  Creating indexes on the ''INTERFACE_LINE_ATTRIBUTE%'' columns can improve the performance of AutoInvoice.
',
      p_solution               => 'Review the section on Creating Indexes in [1083467/KB785164], How to Setup AutoInvoice For Optimal Performance.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: AR_AI_INDEXES');



debug('begin add_signature: AR_AI_INDEX_COLUMNS');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5175',
      p_sig_id                 => 'AR_AI_INDEX_COLUMNS',
      p_sig_sql                => 'select a.table_name, a.index_name, a.owner, a.status, b.column_position, b.column_name
from all_indexes a, all_ind_columns b
where a.index_name = b.index_name
and a.table_name in (''RA_CUSTOMER_TRX_ALL'',''RA_CUSTOMER_TRX_LINES_ALL'',
                     ''RA_INTERFACE_LINES_ALL'',''RA_INTERFACE_DISTRIBUTIONS_ALL'',
                     ''RA_INTERFACE_SALESCREDITS_ALL'')
order by 1,2,5',
      p_title                  => 'Indexes on Transaction Tables',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Existing indexes on transaction tables ',
      p_solution               => 'For optimal AutoInvoice performance, you are advised to create indexes on the Header and/or Line attribute columns. <br>
<ul>
<li> For RA_CUSTOMER_TRX_ALL, you should have indexes on the INTERFACE_HEADER_ATTRIBUTE% columns that you use for AutoInvoice.</li>
<li> For RA_CUSTOMER_TRX_LINES_ALL and RA_INTERFACE_% tables, you should have indexes on the INTERFACE_LINE_ATTRIBUTE% columns that you use for AutoInvoice.</li>
</ul>

Define unique, concatenated indexes on the columns which make up the line/header transaction flexfield that is used. <br>
If you do not use any of the Interface tables for AutoInvoice, then you do not need to create indexes on that table.<br>

For more details, review:
<ul>
<li>How to Setup AutoInvoice For Optimal Performance [1083467/KB785164]</li>
<li>Oracle Receivables User Guide, for how to index the transaction flexfields</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '4'
      );
