      p_sig_repo_id            => '31880',
      p_sig_id                 => 'EBS_FIN_AR_GEN_TABLE_STATS_WITH_DBMS',
      p_sig_sql                => 'SELECT  owner, table_name, last_analyzed
FROM   dba_tables d
WHERE  last_analyzed IS NOT NULL
AND      owner in (''AR'', ''ZX'', ''XLA'')
AND      NOT EXISTS (
  SELECT 1
  FROM   fnd_stats_hist f
  WHERE f.schema_name = d.owner
  AND     f.object_name = d.table_name
