debug('begin add_signature: AR_GEN_LEDGER');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '2931',
      p_sig_id                 => 'AR_GEN_LEDGER',
      p_sig_sql                => 'select a.target_ledger_id ledger_id, 
       a.target_ledger_name ledger_name, 
       a.target_currency_code currency_code,
       rel.sla_accounting_method_code SLAM, 
       a.target_ledger_category_code ledger_type, 
       a.application_id,
       rel.chart_of_accounts_id,
       fifs.id_flex_structure_name CHART_OF_ACCOUNTS_NAME,
       rel.BAL_SEG_COLUMN_NAME ,
       rel.DAILY_TRANSLATION_RATE_TYPE
