       gl_ledgers rel,
       fnd_id_flex_structures_tl fifs
where  b.ledger_id = ##$$LEDGERID$$##
and    rel.ledger_id = a.target_ledger_id 
and    a.primary_ledger_id = b.ledger_id
and    a.application_id in (222,101)
and    fifs.ID_FLEX_NUM = b.CHART_OF_ACCOUNTS_ID 
and    fifs.APPLICATION_ID = 101 
and    fifs.ID_FLEX_CODE = ''GL#'' 
and    fifs.language = userenv(''LANG'') 
order by a.target_ledger_category_code',
