AND ifs.id_flex_num = glsob.chart_of_accounts_id
AND glsob.ledger_id = ##$$LEDGERID$$##
AND frt.responsibility_id = ##$$RESP_ID$$##
AND ifs.id_flex_code = ''GL#''
ORDER BY ifs.segment_num,
