debug('begin add_signature: AR_GEN_C_CODE');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14262',
      p_sig_id                 => 'AR_GEN_C_CODE',
      p_sig_sql                => 'select substr(que.filename,1,instr(que.filename,''.'')-1) "Filename", que.version
from (
select files.filename filename,files.subdir subdir,
file_version.version version,
rank()over(partition by files.filename
order by file_version.version_segment1 desc,
file_version.version_segment2 desc,file_version.version_segment3 desc,
file_version.version_segment4 desc,file_version.version_segment5 desc,
file_version.version_segment6 desc,file_version.version_segment7 desc,
file_version.version_segment8 desc,file_version.version_segment9 desc,
file_version.version_segment10 desc,
file_version.translation_level desc) as rank1
from ad_file_versions file_version,
(
select filename, app_short_name, subdir, file_id
from ad_files
where app_short_name in (''AR'') and lower(filename) like ''%.o''
) files
where files.file_id = file_version.file_id
) que
where rank1 = 1
order by 1,2',
      p_title                  => 'Oracle Receivables .o (c-code) File Versions',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'Could not locate Oracle Receivables (AR) .o (c-code) file versions.',
      p_solution               => 'Please ensure that you have installed the Oracle Receivables (AR) application.',
      p_success_msg            => 'This is a data collection of Oracle Receivables (AR) .o (c-code) file versions from executables.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('N','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: AR_GEN_C_CODE');



debug('begin add_signature: AR_GEN_PROFILES');
   l_info('##MASK##LEVEL VALUE'):= 'NO_MASK';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5868',
      p_sig_id                 => 'AR_GEN_PROFILES',
      p_sig_sql                => 'SELECT user_profile_option_name "Profile Option",
a.profile_option_value "Profile Value",
DECODE(a.level_id, 10001, ''Site'',
10002, ''Application'',
10003, ''Responsibility'',
10004, ''User'') "Level",
DECODE(a.level_id, 10001, ''Site'', 
                   10002, b.application_short_name, 
                   10003, c.responsibility_name, 
                   10004, ##$$A$$##.mask_text(d.user_name,''##$$M$$##'')) "Level Value",
c.responsibility_id
FROM 
  fnd_profile_options e
  INNER JOIN fnd_profile_options_tl t ON t.profile_option_name = e.profile_option_name AND t.LANGUAGE = ''US''
  LEFT JOIN fnd_profile_option_values a ON e.application_id = a.application_id AND e.profile_option_id = a.profile_option_id
  LEFT JOIN fnd_application b ON a.level_value = b.application_id
  LEFT JOIN fnd_responsibility_tl c ON a.level_value = c.responsibility_id AND nvl(c.LANGUAGE,''US'') = ''US''
  LEFT JOIN fnd_user d ON a.level_value = d.user_id
WHERE 
  ((e.application_id in (222,7003))
   or (t.user_profile_option_name in (''GL: Data Access Set'', ''SLA: Additional Data Access Set'',
       ''SLA: Enable Data Access Set Security in Subledger'')))
  AND ((a.level_id = 10003 AND a.level_value = ##$$RESP_ID$$##)
       OR (a.level_id = 10004 AND d.user_name = ''##$$USERNAME$$##'')
       OR (a.level_id = 10001 )
       OR (a.level_id = 10002 )
       OR a.level_id IS NULL)
ORDER BY 
  e.profile_option_name,
  a.level_id DESC',
      p_title                  => 'AR Profile Options',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'This is a data collection of settings for AR system profile options.',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('RS','RS'),
