debug('begin add_signature: EBS_FIN_AR_GEN_MOAC');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '22835',
      p_sig_id                 => 'EBS_FIN_AR_GEN_MOAC',
      p_sig_sql                => 'select decode(to_char(pov.level_id),''10001'', ''Site'',''10002'', ''Application'',''10003'', ''Responsibility'', ''10004'', ''User'', ''10005'', ''Server'',''10006'', ''Org'',''10007'', ''Servresp'', ''???'') "Level" ,
       decode(to_char(pov.level_id),''10001'', ''Site'',
              ''10002'', nvl(app.application_short_name,to_char(pov.level_value)),''10003'', nvl(rsp.responsibility_name,to_char(pov.level_value)),
			  ''10004'', nvl(usr.user_name, to_char(pov.level_value)),
              ''10005'', svr.node_name,''10006'', org.name,''10007'', pov.level_value ||'', ''|| pov.level_value_application_id ||'', ''|| pov.level_value2,''???'') "Context", 
        n.user_profile_option_name "Profile Option",
        pov.profile_option_value "Profile Value"
        from   fnd_profile_options po,
               fnd_profile_option_values pov,
               fnd_profile_options_tl n,
               fnd_user usr,fnd_application app,fnd_responsibility_vl rsp,fnd_nodes svr,hr_operating_units org
        where  po.profile_option_name in (''ORG_ID'', ''DEFAULT_ORG_ID'', ''XLA_MO_SECURITY_PROFILE_LEVEL'')
        and    pov.application_id = po.application_id
        and    po.profile_option_name = n.profile_option_name
        and    pov.profile_option_id = po.profile_option_id
        and    usr.user_id (+) = pov.level_value
        and    rsp.application_id (+) = pov.level_value_application_id
        and    rsp.responsibility_id (+) = pov.level_value
        and    app.application_id (+) = pov.level_value
        and    svr.node_id (+) = pov.level_value
        and    svr.node_id (+) = pov.level_value2
        and    org.organization_id (+) = pov.level_value
	    and    n.language=''US''
        and (pov.level_id in (10001, 10004, 10005,10006,10007) or ( pov.level_id=10003 and rsp.APPLICATION_ID in (222)) or ( pov.level_id=10002 and app.APPLICATION_ID in (222)))
        order by pov.level_id,"Context", "Profile Option"',
      p_title                  => 'MOAC Setup for Receivables',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'This is a data collection of settings for MOAC (Receivables only)',
      p_solution               => '',
      p_success_msg            => '',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_GEN_MOAC');



