debug('begin add_signature: AR_GEN_DUP_GL_CODE_COMBI');
   l_info('##MASK##USER_NAME'):= 'DISPLAY_BOTH_25_PCNT_WORD';
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '12678',
      p_sig_id                 => 'AR_GEN_DUP_GL_CODE_COMBI',
      p_sig_sql                => 'SELECT cck.concatenated_segments,
       cck.code_combination_id,
       cck.chart_of_accounts_id,
       cck.template_id,
       cck.last_update_date,
       ffu.user_name
  FROM gl_code_combinations_kfv cck,
       fnd_user ffu
 WHERE ffu.user_id = cck.last_updated_by
   AND (cck.concatenated_segments,
        cck.chart_of_accounts_id,
        NVL(cck.template_id, -99)) IN
     (SELECT cck.concatenated_segments,
             cck.chart_of_accounts_id,
             NVL(cck.template_id, -99)
        FROM gl_code_combinations_kfv cck,
             gl_ledgers gl
       WHERE gl.ledger_id = ##$$LEDGERID$$##
        AND gl.chart_of_accounts_id = cck.chart_of_accounts_id
   GROUP BY cck.concatenated_segments,
            cck.chart_of_accounts_id,
            NVL(cck.template_id, -99)
   HAVING COUNT(*) >1)
 ORDER BY cck.concatenated_segments,
       cck.last_update_date',
      p_title                  => 'Duplicate GL Code Combination Segments',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Found records with duplicate GL code combination segments. This could raise EU02 errors during Journal Import.',
      p_solution               => '<ul><li>The analyzer has identified issue described in [258628/KB780485]</li>
<li>Please log a Service Request and upload this analyzer output.</li>
</ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: AR_GEN_DUP_GL_CODE_COMBI');



