debug('begin add_signature: EBS_FIN_AR_AI_PERF_CM_NOTE_2033242_1_121');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '29210',
      p_sig_id                 => 'EBS_FIN_AR_AI_PERF_CM_NOTE_2033242_1_121',
      p_sig_sql                => 'SELECT subdir,
       filename,
       VERSION
  FROM (SELECT a.filename,
        v.VERSION,
        a.subdir,
        ROW_NUMBER () OVER (PARTITION BY a.subdir, a.filename ORDER BY v.version_segment1 DESC,
                v.version_segment2 DESC,
                v.version_segment3 DESC,
                v.version_segment4 DESC,
                v.version_segment5 DESC,
                v.version_segment6 DESC,
                v.version_segment6 DESC,
                v.version_segment7 DESC,
                v.version_segment8 DESC,
                v.version_segment9 DESC,
                v.version_segment10 DESC) num
          FROM apps.ad_file_versions v,
               apps.ad_files a
         WHERE v.file_id = a.file_id
           AND a.filename =''ARTECMMB.pls''
           AND a.subdir = ''patch/115/sql'')
WHERE num = 1
AND substr(VERSION,17) < 58',
      p_title                  => 'Low Version of ARTECMMB.pls - Possible Performance Issue in 12.1.X',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Version of ARTECMMB.pls is too low and can cause a performance issue',
      p_solution               => '<ul><li>The analyzer has identified the problem described in [2033242/KB775603]</li>
<li>Please review the note above and implement the solution to avoid performance issues in the future</li>
</ul>
',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('W','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '1'
      );
   l_info.delete;
debug('end add_signature: EBS_FIN_AR_AI_PERF_CM_NOTE_2033242_1_121');



