debug('begin add_signature: AR_AI_OPEN_CALENDAR_AR');
   l_info('##SHOW_SQL##'):= 'Y';
  add_signature(
      p_sig_repo_id            => '7575',
      p_sig_id                 => 'AR_AI_OPEN_CALENDAR_AR',
      p_sig_sql                => 'SELECT led.name "Name", led.user_period_type "Period Type",
       count(ps.period_name) "Number of Periods Defined",
       count(decode(ps.closing_status,''O'', ps.period_name, null)) "Number of Periods Open",
       (select v.first_ledger_period_name || 
               '' (Start Date = '' || s.start_date || '' to '' || s.end_date || '')'' 
        from GL_LEDGERS_V v, GL_PERIOD_STATUSES s 
        where v.ledger_id = ##$$SOB_ID$$## 
        and s.period_name = v.first_ledger_period_name 
        and s.application_id = 222 
        and v.ledger_id = s.ledger_id) "First Ever Opened Period" ,
       (select v.latest_opened_period_name || 
               '' (Start Date = '' || s.start_date || '' to '' || s.end_date || '')'' 
        from GL_LEDGERS_V v, GL_PERIOD_STATUSES s 
        where v.ledger_id = ##$$SOB_ID$$## 
        and s.period_name = v.latest_opened_period_name 
        and s.application_id = 222 
        and v.ledger_id = s.ledger_id) "Latest Open Period"
FROM   GL_LEDGERS_V led,
       GL_PERIOD_STATUSES ps
WHERE  led.ledger_id = ps.ledger_id (+)
AND    ps.application_id (+) = 222
AND    led.ledger_id = ##$$SOB_ID$$##
GROUP BY led.name, led.user_period_type',
      p_title                  => 'Open Calendar Periods - Oracle Receivables',
      p_fail_condition         => 'NRS',
      p_problem_descr          => 'No calendar periods found for Oracle Receivables.',
      p_solution               => 'Please review the Oracle Receivables Implementation Guide for instructions on how to set up your calendar.',
      p_success_msg            => 'Displaying calendar periods for Oracle Receivables.',
      p_print_condition        => nvl('ALWAYS','ALWAYS'),
      p_fail_type              => nvl('I','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('P','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: AR_AI_OPEN_CALENDAR_AR');



