---------------------------------
-- MAIN ENTRY POINT
---------------------------------
PROCEDURE main(
            p_user_name                    IN VARCHAR2    DEFAULT NULL
           ,p_resp_id                      IN NUMBER      DEFAULT NULL
           ,p_org_id                       IN VARCHAR2    DEFAULT NULL
           ,p_batch_source_id              IN NUMBER      DEFAULT NULL
           ,p_col_name                     IN VARCHAR2    DEFAULT 'INTERFACE_LINE_ATTRIBUTE1'
           ,p_col_value                    IN VARCHAR2    DEFAULT NULL
           ,p_apps_check                   IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 5000
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

 IS

  l_sql_result VARCHAR2(1);
  l_step       VARCHAR2(5);
  --l_analyzer_end_time   TIMESTAMP;

BEGIN

  l_step := '1';
  initialize_globals;

  -- Workaround for handling debugging before file init
  g_debug_mode := nvl(p_debug_mode, 'Y');
  g_params_string := '';



  l_step := '10';
  initialize_files;

  analyzer_title := 'Receivables AutoInvoice Analyzer';
  analyzer_title := regexp_replace('EBS ' || analyzer_title, '(\S+\s)\1', '\1', 1, 0, 'i');  -- EBSAF-243

  l_step := '15';
   validate_parameters(
     p_user_name                    => upper(p_user_name)
    ,p_resp_id                      => p_resp_id
    ,p_org_id                       => p_org_id
    ,p_batch_source_id              => p_batch_source_id
    ,p_col_name                     => upper(p_col_name)
    ,p_col_value                    => p_col_value
    ,p_apps_check                   => upper(p_apps_check)
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  l_step := '20';
  set_cloud_flag;

  l_step := '23';
  set_snap_days;

  l_step := '25';
  print_page_header;

  l_step := '30';
  print_rep_header(analyzer_title);
  --print_execdetails;
  print_feedback;
  print_parameters;
  print_whatsnew;

  l_step := '40';
  load_signatures;

  l_step := '45';
  create_hyperlink_table;

  l_step := '50';
  initialize_hidden_xml;

  -- Start of Sections and signatures
  l_step := '60';
  debug('begin section: Main Section');
  -- Print the menu of the section screen
  start_main_section;

debug('begin section: INTERFACE_DATA');
IF g_col_value is not null THEN
   start_section('Interface Data for '||g_cond_title||'', 'INTERFACE_DATA');
      set_item_result(run_stored_sig('AR_AI_RA_INTERFACE_LINES_ALL'));
      set_item_result(run_stored_sig('AR_AI_RA_INTERFACE_DISTRIBUTIONS_ALL'));
      set_item_result(run_stored_sig('EBS_FIN_AR_AI_GL_ACCTS'));
      set_item_result(run_stored_sig('AR_AI_RA_INTERFACE_SALESCREDITS_ALL'));
      set_item_result(run_stored_sig('AR_AI_RA_INTERFACE_ERRORS_ALL'));
      set_item_result(run_stored_sig('AR_AI_AR_INTERFACE_CONTS_ALL'));
      set_item_result(run_stored_sig('AR_AI_AR_DEFERRAL_REASONS'));
      set_item_result(run_stored_sig('AR_AI_RA_CUST_TRX_TYPES_ALL'));
      set_item_result(run_stored_sig('AR_AI_RA_TERMS_B'));
      set_item_result(run_stored_sig('EBS_FIN_AR_AI_IBY_TX_EXT'));
      set_item_result(run_stored_sig('EBS_FIN_AR_AI_IBY_PMT_INSTR_USES_ALL_WRT_PMT_TRXN_EXT'));
      set_item_result(run_stored_sig('EBS_FIN_AR_AI_IBY_PMT_INSTR_USES_ALL_WRT_BILLTO_CUST'));
      set_item_result(run_stored_sig('EBS_FIN_AR_AI_IBY_EXTERNAL_PAYERS'));
      set_item_result(run_stored_sig('EBS_FIN_AR_AI_RA_RULES'));
      set_item_result(run_stored_sig('AR_AI_RA_BATCH_SOURCES_ALL'));
